[{"order":1,"type":"heading","text":"Data Types, Field Values, and Nested Maps in Firebase Firestore"},{"order":2,"type":"paragraph","text":"Firebase Firestore is a flexible, scalable NoSQL cloud database for mobile, web, and server development. Understanding how Firestore stores and structures data through various data types, field values, and nested maps is essential for building robust applications."},{"order":3,"type":"subheading","text":"Supported Data Types in Firestore"},{"order":4,"type":"paragraph","text":"Firestore documents contain fields that map to specific values. Each field in Firestore has a designated data type. The database supports a wide range of types to handle diverse application needs."},{"order":5,"type":"bullet_point","text":"String: Text data, encoded in UTF-8."},{"order":6,"type":"bullet_point","text":"Number: Integers and floating-point numbers."},{"order":7,"type":"bullet_point","text":"Boolean: True or false values."},{"order":8,"type":"bullet_point","text":"Array: An ordered list of values of any supported data type."},{"order":9,"type":"bullet_point","text":"Timestamp: Date and time tracking with microsecond precision."},{"order":10,"type":"bullet_point","text":"GeoPoint: Latitude and longitude coordinates."},{"order":11,"type":"bullet_point","text":"Reference: A pointer to a specific document in your database."},{"order":12,"type":"bullet_point","text":"Null: A dedicated null value type."},{"order":13,"type":"subheading","text":"Working with Field Values"},{"order":14,"type":"paragraph","text":"When writing data to Firestore, you define fields and their corresponding values. You can also use special sentinel field values provided by the SDK, such as server timestamps or array unions."},{"order":15,"type":"code","text":"const { initializeApp } = require('firebase/app');
const { getFirestore, doc, setDoc, serverTimestamp } = require('firebase/firestore');

// Initialize Firestore
const db = getFirestore();

async function createUserProfile(userId) {
  await setDoc(doc(db, 'users', userId), {
    username: 'johndoe',
    email: 'john@example.com',
    age: 30,
    isActive: true,
    createdAt: serverTimestamp()
  });
}"},{"order":16,"type":"subheading","text":"Using Nested Maps"},{"order":17,"type":"paragraph","text":"Firestore allows you to structure documents hierarchically using maps (sometimes referred to as dictionaries or objects). Nested maps let you group related fields together within a single document, avoiding the need for unnecessary subcollections."},{"order":18,"type":"code","text":"async function createUserWithNestedMap(userId) {
  await setDoc(doc(db, 'users', userId), {
    personalInfo: {
      firstName: 'Jane',
      lastName: 'Doe',
      contact: {
        phone: '555-0192',
        preferredMethod: 'email'
      }
    },
    settings: {
      theme: 'dark',
      notifications: true
    }
  });
}"},{"order":19,"type":"subheading","text":"Querying and Updating Nested Fields"},{"order":20,"type":"paragraph","text":"You can target nested fields directly using dot notation in update operations. This allows you to modify specific properties inside a nested map without overwriting the entire map object."},{"order":21,"type":"code","text":"const { updateDoc } = require('firebase/firestore');

async function updateTheme(userId, newTheme) {
  const userRef = doc(db, 'users', userId);

  // Using dot notation to update a nested field
  await updateDoc(userRef, {
    "settings.theme": newTheme
  });
}"},{"order":22,"type":"paragraph","text":"By mastering data types, utilizing correct field values, and properly organizing nested maps, you can design a clean, highly queryable, and performant Firestore schema for your application."}]
